<script setup lang="ts">
import { computed, onUnmounted, ref } from 'vue'
import AppIcon from '../components/AppIcon.vue'
import EmptyStateArt from '../components/EmptyStateArt.vue'
import ChoiceSelect from '../components/ChoiceSelect.vue'
import { kindLabels, statusLabels, type DemoTask } from '../lib/model'
import { cancelTask, openTaskResult, tasks, refreshTasks, resumeTask, retryTask } from '../lib/workbench'
const kind = ref('all'), status = ref('all'), detail = ref<DemoTask | null>(null), refreshedAt = ref(''), now = ref(Date.now()), closeButton = ref<HTMLButtonElement>()
const kindChoices = [{ value: 'all', label: '全部类型' }, ...Object.entries(kindLabels).map(([value, label]) => ({ value, label }))]
const statusChoices = [{ value: 'all', label: '全部状态' }, ...Object.entries(statusLabels).map(([value, label]) => ({ value, label }))]
let priorFocus: HTMLElement | null = null
const ticker = setInterval(() => { now.value = Date.now() }, 1000)
onUnmounted(() => { clearInterval(ticker) })
const filtered = computed(() => tasks.filter(t => (kind.value === 'all' || t.kind === kind.value) && (status.value === 'all' || t.status === status.value)))
const duration = (task: DemoTask) => task.duration || `${(((task.endedAt ?? now.value) - task.startedAt) / 1000).toFixed(1)} s`
async function refresh() { try { await refreshTasks(); refreshedAt.value = '已刷新 · ' + new Date().toLocaleTimeString('zh-CN') } catch (e) { refreshedAt.value = '刷新失败：' + String(e) } }
async function reopen(task: DemoTask) { try { await openTaskResult(task); close() } catch (e) { refreshedAt.value = '读取失败：' + String(e) } }
async function resume(task: DemoTask) { try { await resumeTask(task); close() } catch (e) { refreshedAt.value = '续跑失败：' + String(e) } }
function show(task: DemoTask) { priorFocus = document.activeElement as HTMLElement; detail.value = task; setTimeout(() => closeButton.value?.focus(), 0) }
function close() { detail.value = null; priorFocus?.focus() }
function trap(event: KeyboardEvent) { if (event.key === 'Escape') { close(); return }; if (event.key !== 'Tab') return; const buttons = Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('button:not(:disabled)')); if (event.shiftKey && document.activeElement === buttons[0]) { buttons[buttons.length - 1]?.focus(); event.preventDefault() } else if (!event.shiftKey && document.activeElement === buttons[buttons.length - 1]) { buttons[0]?.focus(); event.preventDefault() } }
</script>
<template><div class="jobs-page"><section v-for="task in tasks.filter(t=>t.resultError)" :key="task.id" class="panel activity-panel"><p class="error-text">{{ task.id }} · {{ task.resultError }}</p><button class="btn sm" @click="retryTask(task)">重试读取任务</button></section><div class="metrics-row"><div class="panel metric"><span>本次任务</span><strong>{{ tasks.length.toString().padStart(2,'0') }}</strong></div><div class="panel metric"><span>已完成</span><strong>{{ tasks.filter(t => t.status === 'completed').length.toString().padStart(2,'0') }}</strong></div><div class="panel metric"><span>运行中</span><strong>{{ tasks.filter(t => t.status === 'running').length.toString().padStart(2,'0') }}</strong></div></div><section class="panel jobs-panel"><div class="jobs-toolbar"><div class="filter-group"><ChoiceSelect id="jobs-kind-filter" v-model="kind" label="类型" :options="kindChoices" /><ChoiceSelect id="jobs-status-filter" v-model="status" label="状态" :options="statusChoices" /></div><button class="btn" @click="refresh"><AppIcon name="refresh" :size="15" />刷新记录</button></div><p v-if="refreshedAt" class="refresh-note" role="status">{{ refreshedAt }}</p>
    <div v-if="!filtered.length" class="empty-state jobs-empty"><EmptyStateArt /><h3>{{ tasks.length ? '没有符合条件的任务' : '暂无任务' }}</h3><p>{{ tasks.length ? '请调整筛选条件。' : '生成单次、批量或扫描后显示记录。' }}</p><p class="hint">任务持久化保存在后端输出目录。</p></div>
    <div v-else class="table-scroll"><table><thead><tr><th>真实任务 / 时间</th><th>类型</th><th>参数摘要</th><th>状态</th><th>耗时</th><th>操作</th></tr></thead><tbody><tr v-for="task in filtered" :key="task.id"><td><span class="code task-id">{{ task.id }}</span><small class="table-time">{{ new Date(task.startedAt).toLocaleTimeString('zh-CN') }}</small></td><td>{{ kindLabels[task.kind] }}</td><td class="task-summary">{{ task.summary }}</td><td><span :class="['badge', 'task-' + task.status]">{{ statusLabels[task.status] }}</span><small v-if="task.status === 'running'" class="table-time mono">{{ task.progress }}%</small></td><td class="mono">{{ duration(task) }}</td><td><button class="btn sm" @click="show(task)">详情<AppIcon name="chevron" :size="13" /></button></td></tr></tbody></table></div><div class="jobs-footnote"><span>真实后端任务记录</span></div>
  </section><Transition name="drawer"><div v-if="detail" class="modal-backdrop" @click.self="close"><section class="detail-drawer" role="dialog" aria-modal="true" aria-labelledby="task-detail-title" @keydown="trap"><div class="panel-heading"><h2 id="task-detail-title">真实任务详情</h2><button ref="closeButton" class="icon-btn" aria-label="关闭任务详情" @click="close"><AppIcon name="close" /></button></div><span :class="['badge', 'task-' + detail.status]">{{ statusLabels[detail.status] }}</span><dl class="detail-list"><dt>任务 ID</dt><dd class="code">{{ detail.id }}</dd><dt>类型</dt><dd>{{ kindLabels[detail.kind] }}</dd><dt>参数摘要</dt><dd>{{ detail.summary }}</dd><dt>开始时间</dt><dd>{{ new Date(detail.startedAt).toLocaleString('zh-CN') }}</dd><dt>后端耗时</dt><dd class="mono">{{ duration(detail) }}</dd><template v-if="detail.detail"><dt>状态说明</dt><dd>{{ detail.detail }}</dd></template><dt>来源</dt><dd class="code">Python / 实际 manifest</dd></dl><button v-if="detail.status === 'running'" class="btn danger full" @click="cancelTask(detail)">取消任务</button><button v-if="detail.status === 'completed'" class="btn primary full" @click="reopen(detail)">查看结果<AppIcon name="arrow" :size="16" /></button><button v-if="detail.resumable" class="btn primary full" @click="resume(detail)">从确定计划续跑</button><pre v-if="detail.events?.length" class="hint" style="white-space:pre-wrap">{{ detail.events.join('\n') }}</pre></section></div></Transition></div></template>
